const personalDetails=require('../models/persondetail');
const User=require('../models/user');
exports.form=async(req,res)=>{
    try{ 
        const {
            current_illnesses,
            checkmedication,
            checkweight,
            checkfeel_well_today,
            checkeat_in_last_4_hours,
            checksleep,
            checknot_to_donate,
            checkalcohol_within_the_last24hours,
            checksmoked_within_lasthour,
            checkconsent,
            insurance_provider,
            policy_number
        }=req.body;
     const user_id = req.user.id;
     const user = await User.findById(user_id);
        if (!user) {
          return res.status(404).json({ message: "User not found or unauthorized." });
        } 
const person = await personalDetails.findOne({ iseligible: true });

if (person) {
   if(current_illnesses!='NA'){
     return res.status(400).json({ message: "You can not donate blood with illness" });
   }
   if(checkmedication){
     return res.status(400).json({ message: "You can not donate blood under medication" });
   }
   if(!checkweight){
      return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checkfeel_well_today){
     return res.status(400).json({ message: "You can not donate blood with not well" });
   }
   if(checkeat_in_last_4_hours){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checksleep){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checknot_to_donate){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checkalcohol_within_the_last24hours){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checksmoked_within_lasthour){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
   if(checkconsent){
     return res.status(400).json({ message: "You can not donate blood with less then 50 kg weight" });
   }
} else {
    console.log("No eligible person found");
}

    }catch(e){

    }
}
